from point import Point
from disc import Disc
from disc_from_two_points import disc_from_two_points
from disc_from_three_points import disc_from_three_points
from get_distance import get_distance

def MiniDiscWith2Points(points: list[Point], q1: Point, q2: Point):    
    disc = disc_from_two_points(q1, q2)
    
    for point in points:
        if (get_distance(disc.center, point) > disc.radius):
            disc = disc_from_three_points(q1, q2, point)

    return disc

#tests generated by GPT 5.6
# Empty list: the result is the initial disc through q1 and q2
assert MiniDiscWith2Points(
    [],
    Point(-1, 0),
    Point(1, 0)
) == Disc(
    Point(0, 0),
    1
)


# Additional point inside the initial disc
assert MiniDiscWith2Points(
    [Point(0, 0)],
    Point(-1, 0),
    Point(1, 0)
) == Disc(
    Point(0, 0),
    1
)


# Additional point on the boundary
assert MiniDiscWith2Points(
    [Point(0, 1)],
    Point(-1, 0),
    Point(1, 0)
) == Disc(
    Point(0, 0),
    1
)


# Additional point outside the initial disc
assert MiniDiscWith2Points(
    [Point(0, 2)],
    Point(-1, 0),
    Point(1, 0)
) == Disc(
    Point(0, 0.75),
    1.25
)


# First point is inside; second point requires a larger disc
assert MiniDiscWith2Points(
    [
        Point(0, 0.5),
        Point(0, 2)
    ],
    Point(-1, 0),
    Point(1, 0)
) == Disc(
    Point(0, 0.75),
    1.25
)


# After enlargement, the last point is already inside the new disc
assert MiniDiscWith2Points(
    [
        Point(0, 2),
        Point(0, 1)
    ],
    Point(-1, 0),
    Point(1, 0)
) == Disc(
    Point(0, 0.75),
    1.25
)
